<?php
namespace qqworld_collector; use qqworld_collector\lib; class bulk_update extends lib { public function __construct() { $args = array( 'public' => 1, 'show_ui' => 1 ); $post_types = get_post_types($args); foreach ($post_types as $post_type) { $screen_id = $post_type == 'attachment' ? 'upload' : 'edit-'.$post_type; add_filter( "bulk_actions-{$screen_id}", array($this, 'add_bulk_actions') ); add_filter( "handle_bulk_actions-{$screen_id}", array($this, 'handle_bulk_actions'), 10, 3 ); } $args = array( 'public' => 1, 'show_ui' => 1 ); $taxonomies = get_taxonomies($args); foreach ($taxonomies as $taxonomy) { $screen_id = 'edit-' . $taxonomy; add_filter( "bulk_actions-{$screen_id}", array($this, 'add_bulk_actions') ); add_filter( "handle_bulk_actions-{$screen_id}", array($this, 'handle_taxonomies_bulk_actions'), 10, 3 ); } add_action( 'admin_notices', array($this, 'admin_notices') ); } public function add_bulk_actions($actions) { $actions['update-object'] = __('Update'); return $actions; } public function handle_bulk_actions( $redirect_to, $doaction, $post_ids ) { switch ($doaction) { case 'update-object': foreach ( $post_ids as $post_id ) { $post = get_post($post_id, ARRAY_A); wp_update_post($post); } $redirect_to = add_query_arg( 'bulk_update_object', count( $post_ids ), $redirect_to ); break; } return $redirect_to; } public function handle_taxonomies_bulk_actions($redirect_to, $doaction, $term_ids) { switch ($doaction) { case 'update-object': foreach ( $term_ids as $term_id ) { $term = get_term($term_id, $_POST['taxonomy'], ARRAY_A); wp_update_term($term_id, $_POST['taxonomy'], $term); } $redirect_to = add_query_arg( 'bulk_update_taxonomies_object', count( $term_ids ), $redirect_to ); break; } return $redirect_to; } public function admin_notices() { if ( ! empty( $_REQUEST['bulk_update_object'] ) ) { $hanler_count = intval( $_REQUEST['bulk_update_object'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Updated %s post.', 'Updated %s posts.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } elseif ( ! empty( $_REQUEST['bulk_update_taxonomies_object'] ) ) { $hanler_count = intval( $_REQUEST['bulk_update_taxonomies_object'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Updated %s term.', 'Updated %s terms.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } } } new bulk_update; ?>